oxy_webhelp_navlinks = {"tocId-d39307e6477":{"topics":[{"title":"SLA Domains","shortdesc":"<p class=\"shortdesc\">SLA Domains in <span class=\"ph\">RSC<\/span> unify data protection policies, providing a         unified approach to manage data protection across various workloads and         environments.<\/p>","href":"saas\/sla_domains.html","attributes":{"data-id":"sla_domains"},"menu":{"hasChildren":true},"tocID":"sla_domains-d39307e6483","next":"sla_domains-d39307e6483"},{"title":"Data center archival locations","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> supports archiving backed-up data from data center workloads to         external storage destinations, including cloud storage providers, NFS shares, S3-compatible         object stores, and tape.<\/p>","href":"archival\/arch_dc_archival_locations.html","attributes":{"data-id":"arch_dc_archival_locations"},"menu":{"hasChildren":true},"tocID":"arch_dc_archival_locations-d39307e7909","next":"arch_dc_archival_locations-d39307e7909"},{"title":"Rubrik Cloud Vault","shortdesc":"<p class=\"shortdesc\">Rubrik Cloud Vault is a Rubrik-managed cloud service that provides isolated and         immutable copies of protected data, enhancing cyber resiliency.<\/p>","href":"saas\/rcv_rubrik_cloud_vault.html","attributes":{"data-id":"rcv_rubrik_cloud_vault"},"menu":{"hasChildren":true},"tocID":"rcv_rubrik_cloud_vault-d39307e10399","next":"rcv_rubrik_cloud_vault-d39307e10399"},{"title":"Cascading archival","shortdesc":"<p class=\"shortdesc\">Using cascading archival, you can increase replicated data redundancy and decrease         data storage costs by archiving replicated snapshots from a replication target Rubrik         cluster to a remote archival location.<\/p>","href":"saas\/cascading_archival.html","attributes":{"data-id":"cascading_archival"},"menu":{"hasChildren":true},"tocID":"cascading_archival-d39307e11357","next":"cascading_archival-d39307e11357"},{"title":"Replication","shortdesc":"<p class=\"shortdesc\">The replication feature directs the Rubrik cluster to send replicas of source       snapshots or backups to a target Rubrik cluster and defines the maximum time to keep the       replica on each cluster.<\/p>","href":"replication\/replication.html","attributes":{"data-id":"replication"},"menu":{"hasChildren":true},"tocID":"replication-d39307e11412","next":"replication-d39307e11412"}]}};